import {html} from 'lit';
import {materialCSS,surface} from './material.js';
const NATIVE = {"svg": "<svg\n          viewBox=\"0 0 240 240\"\n          xmlns=\"http://www.w3.org/2000/svg\"\n          class=\"vacuum-svg\"\n        >\n          <!-- Soft background glow -->\n          <circle\n            cx=\"120\"\n            cy=\"120\"\n            r=\"110\"\n            class=\"glow\"\n            fill=\"var(--vacuum-color)\"\n            opacity=\"0.06\"\n          />\n\n          <!-- Robot body group -->\n          <g class=\"vacuum-body-rotate\">\n            <g class=\"vacuum-body\">\n              <!-- Side brush (front-right, rendered before body so body covers half) -->\n              <g class=\"brush brush-right\">\n                <g class=\"brush-spokes\">\n                  <line\n                    x1=\"174\"\n                    y1=\"76\"\n                    x2=\"174\"\n                    y2=\"64\"\n                    stroke=\"var(--vacuum-color)\"\n                    stroke-width=\"1.2\"\n                    stroke-linecap=\"round\"\n                    opacity=\"0.5\"\n                  />\n                  <line\n                    x1=\"174\"\n                    y1=\"76\"\n                    x2=\"174\"\n                    y2=\"88\"\n                    stroke=\"var(--vacuum-color)\"\n                    stroke-width=\"1.2\"\n                    stroke-linecap=\"round\"\n                    opacity=\"0.5\"\n                  />\n                  <line\n                    x1=\"174\"\n                    y1=\"76\"\n                    x2=\"162\"\n                    y2=\"76\"\n                    stroke=\"var(--vacuum-color)\"\n                    stroke-width=\"1.2\"\n                    stroke-linecap=\"round\"\n                    opacity=\"0.5\"\n                  />\n                  <line\n                    x1=\"174\"\n                    y1=\"76\"\n                    x2=\"186\"\n                    y2=\"76\"\n                    stroke=\"var(--vacuum-color)\"\n                    stroke-width=\"1.2\"\n                    stroke-linecap=\"round\"\n                    opacity=\"0.5\"\n                  />\n                </g>\n                <circle\n                  cx=\"174\"\n                  cy=\"76\"\n                  r=\"2\"\n                  fill=\"var(--vacuum-color)\"\n                  opacity=\"0.5\"\n                />\n              </g>\n\n              <!-- Outer body shell -->\n              <circle\n                cx=\"120\"\n                cy=\"120\"\n                r=\"72\"\n                fill=\"var(--card-background-color, #fff)\"\n                stroke=\"var(--vacuum-color)\"\n                stroke-width=\"2\"\n              />\n\n              <!-- Inner body ring -->\n              <circle\n                cx=\"120\"\n                cy=\"120\"\n                r=\"66\"\n                fill=\"none\"\n                stroke=\"var(--vacuum-color)\"\n                stroke-width=\"0.8\"\n                opacity=\"0.2\"\n              />\n\n              <!-- Bumper arc (front half, prominent) -->\n              <path\n                d=\"M 60 94 A 68 68 0 0 1 180 94\"\n                fill=\"none\"\n                stroke=\"var(--vacuum-color)\"\n                stroke-width=\"3\"\n                stroke-linecap=\"round\"\n                class=\"bumper\"\n              />\n\n              <!-- Direction indicator lines (navigation feel) -->\n              <g class=\"nav-lines\" opacity=\"0.15\">\n                <line\n                  x1=\"120\"\n                  y1=\"56\"\n                  x2=\"120\"\n                  y2=\"74\"\n                  stroke=\"var(--vacuum-color)\"\n                  stroke-width=\"1.5\"\n                />\n                <line\n                  x1=\"88\"\n                  y1=\"63\"\n                  x2=\"96\"\n                  y2=\"78\"\n                  stroke=\"var(--vacuum-color)\"\n                  stroke-width=\"1.5\"\n                />\n                <line\n                  x1=\"152\"\n                  y1=\"63\"\n                  x2=\"144\"\n                  y2=\"78\"\n                  stroke=\"var(--vacuum-color)\"\n                  stroke-width=\"1.5\"\n                />\n              </g>\n\n              <!-- LIDAR turret (static) -->\n              <circle\n                cx=\"120\"\n                cy=\"108\"\n                r=\"14\"\n                fill=\"var(--card-background-color, #fff)\"\n                stroke=\"var(--vacuum-color)\"\n                stroke-width=\"2\"\n                class=\"lidar-housing\"\n              />\n              <circle\n                cx=\"120\"\n                cy=\"108\"\n                r=\"9\"\n                fill=\"none\"\n                stroke=\"var(--vacuum-color)\"\n                stroke-width=\"0.8\"\n                opacity=\"0.25\"\n              />\n\n              <!-- Power button area (center) -->\n              <circle\n                cx=\"120\"\n                cy=\"140\"\n                r=\"8\"\n                fill=\"var(--vacuum-color)\"\n                opacity=\"0.08\"\n                class=\"power-ring\"\n              />\n              <circle\n                cx=\"120\"\n                cy=\"140\"\n                r=\"4\"\n                fill=\"var(--vacuum-color)\"\n                opacity=\"0.25\"\n                class=\"power-dot\"\n              />\n            </g>\n          </g>\n\n          <!-- Dust particles (cleaning state) - sucked toward vacuum -->\n          <g class=\"particles\">\n            <circle\n              class=\"particle p1\"\n              cx=\"120\"\n              cy=\"120\"\n              r=\"2\"\n              fill=\"var(--vacuum-color)\"\n            />\n            <circle\n              class=\"particle p2\"\n              cx=\"120\"\n              cy=\"120\"\n              r=\"1.5\"\n              fill=\"var(--vacuum-color)\"\n            />\n            <circle\n              class=\"particle p3\"\n              cx=\"120\"\n              cy=\"120\"\n              r=\"1.5\"\n              fill=\"var(--vacuum-color)\"\n            />\n            <circle\n              class=\"particle p4\"\n              cx=\"120\"\n              cy=\"120\"\n              r=\"2\"\n              fill=\"var(--vacuum-color)\"\n            />\n            <circle\n              class=\"particle p5\"\n              cx=\"120\"\n              cy=\"120\"\n              r=\"1.5\"\n              fill=\"var(--vacuum-color)\"\n            />\n            <circle\n              class=\"particle p6\"\n              cx=\"120\"\n              cy=\"120\"\n              r=\"1.5\"\n              fill=\"var(--vacuum-color)\"\n            />\n            <circle\n              class=\"particle p7\"\n              cx=\"120\"\n              cy=\"120\"\n              r=\"1\"\n              fill=\"var(--vacuum-color)\"\n            />\n            <circle\n              class=\"particle p8\"\n              cx=\"120\"\n              cy=\"120\"\n              r=\"1\"\n              fill=\"var(--vacuum-color)\"\n            />\n          </g>\n\n          <!-- Dock station (docked state) -->\n          <g class=\"dock-indicator\">\n            <!-- Dock base plate -->\n            <rect\n              x=\"76\"\n              y=\"188\"\n              width=\"88\"\n              height=\"28\"\n              rx=\"8\"\n              fill=\"var(--card-background-color, #fff)\"\n              stroke=\"var(--vacuum-color)\"\n              stroke-width=\"2\"\n            />\n          </g>\n\n          <!-- Return arrow (returning state) -->\n          <g class=\"return-path\">\n            <polygon\n              points=\"120,220 110,206 130,206\"\n              fill=\"var(--vacuum-color)\"\n              stroke=\"var(--vacuum-color)\"\n              stroke-width=\"2\"\n              stroke-linejoin=\"round\"\n              opacity=\"0.55\"\n            />\n          </g>\n        </svg>", "css": "\n    :host {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n\n    .container {\n      width: 200px;\n      height: 200px;\n      position: relative;\n    }\n\n    .vacuum-svg {\n      width: 100%;\n      height: 100%;\n    }\n\n    /* -- Hide state-specific elements by default -- */\n    .particles,\n    .dock-indicator,\n    .return-path {\n      opacity: 0;\n      transition: opacity 400ms ease;\n    }\n\n    /* ======================== */\n    /* CLEANING                 */\n    /* ======================== */\n    .cleaning .vacuum-body {\n      animation: vacuum-wander 12s ease-in-out infinite;\n      transform-origin: 120px 120px;\n    }\n\n    .cleaning .brush-right .brush-spokes {\n      animation: brush-spin 0.6s linear infinite;\n      transform-origin: 174px 76px;\n    }\n\n    .cleaning .particles {\n      opacity: 1;\n    }\n\n    .cleaning .particle {\n      animation: particle-suck 2.4s ease-in infinite;\n      transform-origin: 120px 120px;\n    }\n\n    .cleaning .p1 {\n      animation-delay: 0s;\n    }\n    .cleaning .p2 {\n      animation-delay: -0.3s;\n    }\n    .cleaning .p3 {\n      animation-delay: -0.6s;\n    }\n    .cleaning .p4 {\n      animation-delay: -0.9s;\n    }\n    .cleaning .p5 {\n      animation-delay: -1.2s;\n    }\n    .cleaning .p6 {\n      animation-delay: -1.5s;\n    }\n    .cleaning .p7 {\n      animation-delay: -1.8s;\n    }\n    .cleaning .p8 {\n      animation-delay: -2.1s;\n    }\n\n    .cleaning .p1 {\n      --particle-x: -90px;\n      --particle-y: -25px;\n    }\n    .cleaning .p2 {\n      --particle-x: 90px;\n      --particle-y: 20px;\n    }\n    .cleaning .p3 {\n      --particle-x: -85px;\n      --particle-y: 40px;\n    }\n    .cleaning .p4 {\n      --particle-x: 85px;\n      --particle-y: -35px;\n    }\n    .cleaning .p5 {\n      --particle-x: -65px;\n      --particle-y: 70px;\n    }\n    .cleaning .p6 {\n      --particle-x: 70px;\n      --particle-y: -65px;\n    }\n    .cleaning .p7 {\n      --particle-x: -75px;\n      --particle-y: -55px;\n    }\n    .cleaning .p8 {\n      --particle-x: 80px;\n      --particle-y: 55px;\n    }\n\n    .cleaning .nav-lines {\n      animation: nav-pulse 2s ease-in-out infinite;\n    }\n\n    /* ======================== */\n    /* RETURNING                */\n    /* ======================== */\n    .vacuum-body-rotate {\n      transform-origin: 120px 120px;\n      transform: rotate(0deg);\n      transition: transform 600ms ease-in-out;\n    }\n\n    .returning .vacuum-body-rotate {\n      transform: rotate(180deg);\n    }\n\n    .returning .vacuum-body {\n      animation: returning-drift 3s ease-in-out infinite;\n    }\n\n    .returning .return-path {\n      opacity: 1;\n      animation: return-arrow 1.6s ease-in-out infinite;\n      transform-origin: 120px 210px;\n    }\n\n    .returning .brush-right {\n      opacity: 0.4;\n    }\n\n    /* ======================== */\n    /* DOCKED                   */\n    /* ======================== */\n    .docked .dock-indicator {\n      opacity: 1;\n    }\n\n    .docked .vacuum-body {\n      opacity: 0.75;\n    }\n\n    .docked .glow {\n      animation: docked-glow 4s ease-in-out infinite;\n    }\n\n    .docked .power-ring {\n      animation: charge-pulse 2.5s ease-in-out infinite;\n    }\n\n    .docked .brush-right {\n      opacity: 0.5;\n    }\n\n    /* ======================== */\n    /* ERROR                    */\n    /* ======================== */\n    .error .glow {\n      animation: error-glow 1.8s ease-in-out infinite;\n    }\n\n    /* ======================== */\n    /* IDLE                     */\n    /* ======================== */\n    .idle .vacuum-body {\n      opacity: 0.65;\n    }\n\n    .idle .brush-right {\n      opacity: 0.4;\n    }\n\n    /* ============================== */\n    /* KEYFRAME ANIMATIONS            */\n    /* ============================== */\n\n    @keyframes vacuum-wander {\n      0% {\n        transform: rotate(0deg) translate(0, 0);\n      }\n      15% {\n        transform: rotate(0deg) translate(0, -30px);\n      }\n      25% {\n        transform: rotate(0deg) translate(0, 0);\n      }\n      32% {\n        transform: rotate(-18deg) translate(0, 0);\n      }\n      47% {\n        transform: rotate(-18deg) translate(0, -28px);\n      }\n      57% {\n        transform: rotate(-18deg) translate(0, 0);\n      }\n      63% {\n        transform: rotate(12deg) translate(0, 0);\n      }\n      78% {\n        transform: rotate(12deg) translate(0, -25px);\n      }\n      88% {\n        transform: rotate(12deg) translate(0, 0);\n      }\n      95% {\n        transform: rotate(0deg) translate(0, 0);\n      }\n      100% {\n        transform: rotate(0deg) translate(0, 0);\n      }\n    }\n\n    @keyframes brush-spin {\n      to {\n        transform: rotate(360deg);\n      }\n    }\n\n    @keyframes particle-suck {\n      0% {\n        opacity: 0;\n        transform: translate(var(--particle-x), var(--particle-y)) scale(1.2);\n      }\n      25% {\n        opacity: 0.8;\n      }\n      80% {\n        opacity: 0;\n        transform: translate(\n            calc(var(--particle-x) * 0.82),\n            calc(var(--particle-y) * 0.82)\n          )\n          scale(0.6);\n      }\n      100% {\n        opacity: 0;\n        transform: translate(\n            calc(var(--particle-x) * 0.82),\n            calc(var(--particle-y) * 0.82)\n          )\n          scale(0.6);\n      }\n    }\n\n    @keyframes nav-pulse {\n      0%,\n      100% {\n        opacity: 0.15;\n      }\n      50% {\n        opacity: 0.35;\n      }\n    }\n\n    @keyframes returning-drift {\n      0%,\n      100% {\n        transform: translateY(-6px);\n      }\n      50% {\n        transform: translateY(4px);\n      }\n    }\n\n    @keyframes return-arrow {\n      0%,\n      100% {\n        transform: translateY(-6px);\n        opacity: 0.3;\n      }\n      50% {\n        transform: translateY(4px);\n        opacity: 0.85;\n      }\n    }\n\n    @keyframes docked-glow {\n      0%,\n      100% {\n        opacity: 0.06;\n      }\n      50% {\n        opacity: 0.14;\n      }\n    }\n\n    @keyframes charge-pulse {\n      0%,\n      100% {\n        opacity: 0.08;\n      }\n      50% {\n        opacity: 0.25;\n      }\n    }\n\n    @keyframes error-glow {\n      0%,\n      100% {\n        opacity: 0.08;\n      }\n      50% {\n        opacity: 0.35;\n      }\n    }\n\n    /* Respect prefers-reduced-motion */\n    @media (prefers-reduced-motion: reduce) {\n      .cleaning .vacuum-body,\n      .cleaning .brush-right .brush-spokes,\n      .cleaning .particle,\n      .cleaning .nav-lines,\n      .returning .vacuum-body,\n      .returning .return-path,\n      .docked .glow,\n      .docked .power-ring,\n      .error .glow {\n        animation: none;\n      }\n      .vacuum-body-rotate {\n        transition: none;\n      }\n    }\n  "};
const STYLES = ":host { display:block; }\nha-card {border:1px solid var(--divider-color);border-radius:16px;overflow:hidden;color:var(--primary-text-color);background:var(--ha-card-background,var(--card-background-color));}\n* {box-sizing:border-box;}\nbutton,select,input {font:inherit;}\nbutton {cursor:pointer;color:inherit;background:none;border:0;}\nbutton:disabled {opacity:.45;cursor:default;}\nbutton:focus-visible,select:focus-visible,input:focus-visible {outline:2px solid var(--primary-color);outline-offset:2px;}\nheader {display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 16px;min-height:56px;}\n.title-button {display:flex;align-items:center;gap:10px;text-align:left;padding:0;}\n.title-button ha-state-icon {width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(145deg,rgba(245,251,255,.25),rgba(24,44,61,.42));border:1px solid rgba(245,251,255,.48);box-shadow:inset 0 1px 0 rgba(255,255,255,.54),inset 0 -1px 0 rgba(4,16,29,.22),0 3px 8px rgba(0,0,0,.23);backdrop-filter:blur(6px) saturate(1.16);}\nheader .action {font-size:12px;}\nha-icon {--mdc-icon-size:22px;flex:none;}\n.status-panel {padding:8px 20px 0;}\n.status-title {font-size:32px;line-height:1.2;font-weight:400;}\n.status-meta {display:flex;justify-content:space-between;align-items:center;margin-top:8px;color:var(--secondary-text-color);font-size:14px;}\n.battery {display:flex;align-items:center;gap:6px;font-size:14px;color:var(--secondary-text-color);}\n.battery ha-state-icon {--mdc-icon-size:18px;}\n.robot-animation {display:flex;justify-content:center;margin:0 auto;min-height:200px;}\n.progress-row {display:grid;grid-template-columns:1fr auto;gap:6px;padding:0 16px 12px;font-size:12px;}\nprogress {grid-column:1/-1;width:100%;height:5px;border:0;border-radius:8px;overflow:hidden;accent-color:var(--primary-color);}\nprogress::-webkit-progress-bar {background:var(--divider-color);}\nprogress::-webkit-progress-value {background:var(--primary-color);}\n.stats-grid {display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) minmax(0,1.25fr);border-top:1px solid var(--divider-color);border-bottom:1px solid var(--divider-color);}\n.stat {padding:10px 4px;display:flex;flex-direction:column;gap:3px;min-width:0;}\n.stat+ .stat {border-left:1px solid var(--divider-color);}\n.stat strong {font-size:16px;font-weight:400;}\n.stat span {white-space:normal;hyphens:auto;-webkit-hyphens:auto;overflow-wrap:normal;word-break:normal;font-size:12px;color:var(--secondary-text-color);}\n.actions-row {display:flex;flex-wrap:wrap;gap:8px;padding:12px;}\n.action {display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:8px;border-radius:12px;background:var(--secondary-background-color);font-size:13px;min-height:36px;}\n.action:hover:not(:disabled),.chip:hover:not(:disabled) {background:var(--divider-color);}\n.dock {padding:0 12px 12px;}\n.dock-title {font-size:13px;color:var(--secondary-text-color);padding:4px 0 8px;}\n.dock-grid {display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:8px;}\n.chip {display:flex;align-items:center;gap:8px;text-align:left;border:1px solid var(--divider-color);border-radius:16px;padding:10px;min-width:0;}\n.chip span {font-size:12px;white-space:normal;overflow-wrap:anywhere;}\n.chip small {display:block;margin-top:3px;color:var(--secondary-text-color);font-size:11px;}\n.select-field {display:flex;flex-direction:column;gap:5px;font-size:12px;color:var(--secondary-text-color);min-width:0;}\nselect {width:100%;min-height:38px;border:1px solid var(--divider-color);border-radius:12px;padding:6px 10px;background:var(--card-background-color);color:var(--primary-text-color);}\n.custom-dialog {width:min(920px,calc(100vw - 24px));max-width:none;max-height:calc(100dvh - 32px);margin:auto;padding:0;border:1px solid var(--divider-color);border-radius:16px;background:var(--lg-surface-raised,var(--card-background-color,#202020));-webkit-backdrop-filter:var(--lg-blur,blur(18px));backdrop-filter:var(--lg-blur,blur(18px));color:var(--primary-text-color);overflow:hidden;box-shadow:var(--lg-shadow,0 12px 48px #0009);}\n.custom-dialog[open] {display:flex;flex-direction:column;}\n.custom-dialog::backdrop {background:#0008;}\n.dialog-header {display:flex;align-items:center;gap:12px;justify-content:space-between;padding:20px 24px;flex:none;border-bottom:1px solid var(--divider-color);}\n.dialog-header h2 {font-size:24px;font-weight:500;margin:2px 0 0;}\n.dialog-subtitle {font-size:14px;color:var(--secondary-text-color);}\n.close {display:grid;place-items:center;min-width:48px;min-height:48px;border-radius:50%;}\n.dialog-body {min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:20px 24px;scrollbar-gutter:stable;}\n.choice-group {margin:0 0 24px;border:0;padding:0;min-width:0;}\n.choice-group:last-child {margin-bottom:0;}\n.choice-group legend {margin-bottom:12px;padding:0;font-size:16px;font-weight:500;}\n.choice-group legend small {margin-left:12px;font-weight:400;font-size:12px;color:var(--secondary-text-color);}\n.choice-grid,.room-grid {display:grid;grid-template-columns:repeat(auto-fit,minmax(100px,1fr));gap:10px;}\n.room-grid {grid-template-columns:repeat(4,minmax(0,1fr));}\n.choice-tile {position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;min-height:90px;min-width:0;padding:16px 8px;border:1px solid var(--divider-color);border-radius:16px;font-size:14px;line-height:1.3;text-align:center;touch-action:manipulation;}\n.choice-tile>ha-icon {--mdc-icon-size:28px;color:var(--secondary-text-color);}\n.choice-tile>span {max-width:100%;white-space:normal;overflow-wrap:anywhere;}\n.room-grid .choice-tile {min-height:140px;font-size:17px;gap:16px;}\n.room-grid .choice-tile>ha-icon {--mdc-icon-size:38px;}\n.choice-tile:hover:not(:disabled) {background:var(--secondary-background-color);}\n.choice-tile[aria-pressed=\"true\"] {border-color:var(--primary-color);background:color-mix(in srgb,var(--primary-color) 14%,transparent);box-shadow:inset 0 0 0 1px var(--primary-color);}\n.choice-tile[aria-pressed=\"true\"]>ha-icon {color:var(--primary-color);}\n.choice-tile>ha-icon.selected-mark {position:absolute;top:7px;right:7px;--mdc-icon-size:17px;}\n.dialog-actions {display:flex;align-items:center;justify-content:space-between;gap:12px;flex:none;padding:16px 24px;border-top:1px solid var(--divider-color);}\n.selection-summary {font-size:13px;color:var(--secondary-text-color);}\n.dialog-actions .action {min-height:48px;padding:12px 20px;border-radius:24px;font-size:15px;background:var(--primary-color);color:var(--text-primary-color,#fff);}\n.dialog-actions .action:disabled {background:var(--secondary-background-color);color:var(--secondary-text-color);}\n@media(max-width:600px) {.dialog-header{padding:12px 16px;}.dialog-header h2{font-size:21px;}.dialog-body{padding:16px;scrollbar-gutter:auto;}.room-grid{grid-template-columns:repeat(2,minmax(0,1fr));}.room-grid .choice-tile{min-height:114px;font-size:15px;gap:12px;}.choice-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;}.choice-tile{font-size:12px;min-height:90px;padding:14px 6px;}.dialog-actions{padding:12px 16px;flex-wrap:wrap;}.dialog-actions .action{width:100%;}.selection-summary{width:100%;text-align:center;}.choice-group legend small{display:block;margin:4px 0 0;}}\n.error {color:var(--error-color,#ef5350);font-size:13px;margin:8px 12px;white-space:normal;}\n@media(max-width:450px) {header {align-items:flex-start;}header .action span {max-width:95px;}.status-title {font-size:28px;}.stats-grid {grid-template-columns:repeat(2,minmax(0,1fr));}.stat:nth-child(3),.stat:nth-child(5){border-left:0;}.stat:nth-child(5){grid-column:1/-1;}.stat:nth-child(n+3){border-top:1px solid var(--divider-color);}}\n\n.cleaning-stats {grid-template-columns:repeat(2,minmax(0,1fr));}\n\n/* Dock controls: quiet status toolbar, spacious touch dialog. */\nheader {flex-wrap:wrap;gap:10px;}\n.title-button {flex:1 0 104px;min-height:44px;}\n.title-button strong {font-size:16px;font-weight:700;}\n.dock-mini {display:inline-flex;align-items:center;flex:none;margin-left:auto;gap:0;padding:0;border:0;background:transparent;overflow:visible;}\n.dock-icon-button {display:flex;align-items:center;justify-content:center;gap:3px;min-width:30px;min-height:30px;height:30px;padding:0;border:0;border-radius:50%;background:transparent;touch-action:manipulation;transition:background .15s;}\n.dock-icon-button+ .dock-icon-button {border:0;}\n.dock-icon-button ha-icon {--mdc-icon-size:20px;}\n.dock-icon-button:hover:not(:disabled) {background:color-mix(in srgb,var(--ha-card-background,var(--card-background-color)) 88%,white);}\n.dry-remaining {font-size:11px;white-space:nowrap;font-variant-numeric:tabular-nums;}\n.primary-actions {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));padding:12px 12px 8px;}\n.primary-actions .action {min-height:48px;border-radius:16px;border:1px solid var(--divider-color);font-size:14px;}\n.primary-actions .action:first-child {color:#e7f5ff;background:color-mix(in srgb,var(--primary-color) 25%,var(--lg-surface-raised,transparent));border-color:var(--lg-outline-bright,var(--primary-color));box-shadow:0 0 0 1px rgba(174,222,255,.92),0 0 24px rgba(28,130,255,.68),inset 0 0 18px rgba(44,147,255,.18);transition:background-color var(--lg-motion-duration,180ms) ease,box-shadow var(--lg-motion-duration,180ms) ease;}\n.secondary-actions {padding:0 12px 12px;}\n.secondary-actions .action {min-height:44px;border:1px solid var(--divider-color);border-radius:16px;flex:1 1 auto;}\n.dock-launcher-wrap {padding:0 12px 12px;}\n.dock-launcher {width:100%;display:flex;align-items:center;gap:12px;text-align:left;min-height:72px;padding:12px 14px;border:1px solid var(--divider-color);border-radius:16px;background:var(--secondary-background-color);touch-action:manipulation;}\n.dock-launcher>span:nth-child(2) {flex:1;}\n.dock-launcher strong {font-size:14px;font-weight:500;}\n.dock-launcher small {display:block;color:var(--secondary-text-color);font-size:12px;margin-top:4px;}\n.dock-launcher-icon,.dock-heading-icon {display:grid;place-items:center;width:42px;height:42px;border-radius:14px;background:color-mix(in srgb,var(--primary-color) 12%,transparent);color:var(--primary-color);}\n.dock-launcher>ha-icon {color:var(--secondary-text-color);}\n.dock-launcher:hover {border-color:var(--primary-color);}\n.dock-dialog {width:min(680px,calc(100vw - 24px));}\n.dock-heading {display:flex;align-items:center;gap:12px;min-width:0;}\n.dock-dialog .dialog-body {padding:20px;}\n.dock-dialog .dock-grid {grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0;}\n.dock-tile {position:relative;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;min-height:140px;padding:20px 10px;touch-action:manipulation;background:var(--secondary-background-color);}\n.dock-tile>ha-icon {--mdc-icon-size:30px;}\n.dock-tile span {font-size:14px;}\n.dock-tile small {font-size:13px;margin-top:8px;}\n.dock-tile[aria-pressed=\"true\"] {border-color:color-mix(in srgb,var(--green-color) 65%,var(--divider-color));}\n.mode-tile>ha-icon:last-child {position:absolute;right:8px;top:8px;--mdc-icon-size:18px;color:var(--secondary-text-color);}\n.empty-mode-grid {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;}\n.empty-mode-grid .choice-tile {min-height:120px;font-size:16px;}\n.dock-hint {font-size:14px;color:var(--secondary-text-color);white-space:normal;margin:0 0 16px;}\n@media(max-width:600px) {.dock-dialog .dock-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;}.dock-dialog .dialog-body{padding:16px;}.dock-tile{min-height:128px;padding:16px 8px;}.dock-tile span{font-size:13px;}.dock-heading-icon{display:none;}.dock-dialog .dialog-header h2{font-size:20px;}}\n";

const VACUUM_CONTROL_CSS = "\n/* Vacuum hierarchy: only start/custom are raised; the other controls stay flat. */\n:is(#vacuum-card,.custom-dialog) button:not(.glass-primary){\n background:transparent!important;border:1px solid transparent!important;box-shadow:none!important;\n backdrop-filter:none!important;-webkit-backdrop-filter:none!important;\n translate:0;scale:1;transition:scale var(--dash6-button-duration,320ms) cubic-bezier(.22,1.5,.36,1),box-shadow 160ms ease,border-color 160ms ease;\n}\n:is(#vacuum-card,.custom-dialog) button:not(.glass-primary):hover:not(:disabled){border-color:var(--divider-color)!important}\n:is(#vacuum-card,.custom-dialog) button:not(.glass-primary):active:not(:disabled){\n background:transparent!important;box-shadow:inset 0 2px 5px rgba(0,0,0,.38)!important;\n scale:1!important;transform:none!important;translate:0!important;transition-duration:80ms;\n}\n#vacuum-card .primary-actions .glass-primary{background:var(--dash6-button-background)!important;border:var(--dash6-button-border)!important;box-shadow:var(--dash6-button-shadow)!important}\n#vacuum-card .primary-actions .glass-primary:hover:not(:disabled){background:var(--dash6-button-active-background)!important;box-shadow:var(--dash6-button-hover-shadow,var(--dash6-button-shadow))!important;filter:brightness(1.13)}\n#vacuum-card .primary-actions .glass-primary:active:not(:disabled){scale:1!important;translate:0!important;transform:none!important;filter:brightness(.92);box-shadow:var(--dash6-button-pressed-shadow)!important;transition:filter 90ms ease,box-shadow 90ms ease}\n#vacuum-card button.title-button,#vacuum-card button.title-button:not(.glass-primary):not(:disabled):is(:hover,:active),\n#vacuum-card button.battery,#vacuum-card button.battery:not(.glass-primary):not(:disabled):is(:hover,:active){\n border:0!important;box-shadow:none!important;scale:1!important;translate:0!important;\n}\n#vacuum-card .title-button ha-state-icon{width:var(--lg-icon-diameter,48px);height:var(--lg-icon-diameter,48px);min-width:var(--lg-icon-diameter,48px);border-radius:50%;background:var(--dash6-button-background);border:var(--dash6-button-border);box-shadow:var(--dash6-button-shadow)}\n#vacuum-card .dock-launcher-icon{background:transparent;border:0;box-shadow:none}\n#vacuum-card .stats-grid{gap:0;border-top:1px solid var(--divider-color);border-bottom:1px solid var(--divider-color)}\n#vacuum-card .stat{border-radius:0!important;min-height:64px}\n#vacuum-card .stat+.stat{border-left-color:var(--divider-color)!important}\n@media(max-width:450px){#vacuum-card .stat:nth-child(3),#vacuum-card .stat:nth-child(5){border-left-color:transparent!important}#vacuum-card .stat:nth-child(n+3){border-top-color:var(--divider-color)!important}}\n@media(prefers-reduced-motion:reduce){:is(#vacuum-card,.custom-dialog) button{scale:1!important;translate:0!important;transition:none!important}}\n\n.custom-dialog button:not(.glass-primary),.custom-dialog button.glass-primary{background:transparent!important;border:var(--dash6-button-border)!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important}\n.custom-dialog .choice-tile{position:relative}\n.custom-dialog .choice-tile[aria-pressed=\"true\"]{background:var(--dash6-button-background)!important;border:var(--dash6-button-border)!important;box-shadow:inset 0 3px 8px rgba(0,0,0,.62),inset 0 -1px 0 rgba(255,255,255,.18)!important;translate:0 1px;backdrop-filter:var(--dash6-button-filter)!important;-webkit-backdrop-filter:var(--dash6-button-filter)!important}\n.custom-dialog .selected-mark{display:none}\n.custom-dialog .choice-tile[aria-pressed=\"true\"]::after{content:\"\";position:absolute;right:10px;top:10px;width:6px;height:6px;border-radius:50%;background:var(--green-color,#7de7a2);box-shadow:0 0 3px var(--green-color,#7de7a2),0 0 9px var(--green-color,#7de7a2)}\n\n#vacuum-card .dock-locate-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;align-items:stretch}#vacuum-card .dock-locate-row .dock-launcher-wrap{margin:0}#vacuum-card .dock-locate-row button{width:100%;height:100%;min-height:54px;box-sizing:border-box}@media(max-width:450px){#vacuum-card .dock-locate-row{grid-template-columns:1fr}}\n";

const DEFAULT_IDS={};
export function initialize(card,CONFIG){
const ids={...DEFAULT_IDS,vacuum:CONFIG.entity,...CONFIG.entities};

  card._ids = ids;
  card._busy = false;
  card._error = '';
  card._draft = {mode:'vac_and_mop',intensity:'moderate',route:'standard',fan:'balanced',repeat:1,...CONFIG.defaults,rooms:[]};
  card._de = () => (card.hass?.locale?.language || card.hass?.language || navigator.language).startsWith('de');
  const tr = (de,en) => card._de() ? de : en;
  const get = id => card.hass?.states[id];
  const valid = id => get(id) && !['unknown','unavailable'].includes(get(id).state);
  const fmt = (id,state) => {const obj=get(id);return obj ? card.hass.formatEntityState(state===undefined?obj:{...obj,state}) : tr('Unbekannt','Unknown');};
  const more = id => card.dispatchEvent(new CustomEvent('hass-more-info',{detail:{entityId:id},bubbles:true,composed:true}));
  card._perform = async operation => {
    if (card._busy) return;
    card._busy=true; card._error=''; card.requestUpdate();
    try {await operation();} catch(e) {reportError(card,e);}
    finally {card._busy=false;card.requestUpdate();}
  };
  const call = (domain,service,data) => card.hass.callService(domain,service,data);
  card._setOption = async (id,option) => {
    if (!get(id)?.attributes.options?.includes(option)) throw new Error(tr('Nicht unterstützte Option: ','Unsupported option: ')+option);
    await call('select','select_option',{entity_id:id,option});
  };
  card._start = async (draft={mode:'vac_and_mop',intensity:'moderate',route:'standard',fan:'balanced',repeat:1,...CONFIG.defaults,rooms:[]}) => {
    // Validate all parameters before changing any setting or starting a job.
    if(!valid(ids.vacuum))throw new Error(tr('Staubsauger nicht verfügbar','Vacuum unavailable'));
    if(!Number.isInteger(draft.repeat)||draft.repeat<1||draft.repeat>3)throw new Error(tr('Ungültige Anzahl der Durchgänge','Invalid repeat count'));
    for(const [id,value] of [[ids.mode,draft.mode],[ids.intensity,draft.intensity],[ids.route,draft.route]])
      if(!get(id)?.attributes.options?.includes(value)) throw new Error(tr('Ungültige Reinigungseinstellung','Invalid cleaning setting'));
    if(!get(ids.vacuum)?.attributes.fan_speed_list?.includes(draft.fan)) throw new Error(tr('Ungültige Saugstufe','Invalid suction level'));
    if(draft.rooms.some(n=>!CONFIG.areas.some(a=>a.roborock_area_id===n))) throw new Error(tr('Unbekannter Raum','Unknown room'));
    await card._setOption(ids.mode,draft.mode);
    await card._setOption(ids.intensity,draft.intensity);
    await card._setOption(ids.route,draft.route);
    if(draft.mode!=='mop') await call('vacuum','set_fan_speed',{entity_id:ids.vacuum,fan_speed:draft.fan});
    if(draft.rooms.length) await call('vacuum','send_command',{entity_id:ids.vacuum,command:'app_segment_clean',params:[{segments:draft.rooms,repeat:draft.repeat}]});
    else await call('vacuum','start',{entity_id:ids.vacuum});
  };
  card._openCustom = () => {
    card._draft={mode:'vac_and_mop',intensity:'moderate',route:'standard',fan:'balanced',repeat:1,...CONFIG.defaults,rooms:[]};
    card._error='';card.requestUpdate();
    card.updateComplete.then(()=>card.shadowRoot.querySelector('.cleaning-dialog').showModal());
  };
  card._closeCustom = () => card.shadowRoot.querySelector('.cleaning-dialog')?.close();
  card._toggle = id => card._perform(()=>call('switch','toggle',{entity_id:id}));
  card._openDock = () => {card._dockPage='overview';card._error='';card.requestUpdate();card.updateComplete.then(()=>card.shadowRoot.querySelector('.dock-dialog').showModal());};
  card._closeDock = () => card.shadowRoot.querySelector('.dock-dialog')?.close();
  card._dockPage = 'overview';
  card._intermediateWash = () => card._perform(()=>call('switch','turn_on',{entity_id:ids.washing}));
  const svg = document.createElement('div');
  svg.className='animation-fallback';
  svg.attachShadow({mode:'open'}).innerHTML='<style>'+NATIVE.css+'</style><div class="container idle">'+NATIVE.svg+'</div>';
  const fallbackContainer=svg.shadowRoot.querySelector('.container');
  card._nativeAnimation = null;
  card._animation = stateObj => {
    if(customElements.get('ha-state-control-vacuum-status')) {
      if(!card._nativeAnimation) card._nativeAnimation=document.createElement('ha-state-control-vacuum-status');
      card._nativeAnimation.stateObj=stateObj;
      return card._nativeAnimation;
    }
    const state=['cleaning','returning','docked','paused','error'].includes(stateObj.state)?stateObj.state:'idle';
    fallbackContainer.className='container '+state;
    const kind=['cleaning','returning'].includes(state)?'active':'inactive';
    fallbackContainer.style.setProperty('--vacuum-color',`var(--state-vacuum-${state}-color,var(--state-vacuum-${kind}-color,var(--state-${kind}-color)))`);
    return svg;
  };
  const icon = (name,color) => html`<ha-icon .icon=${name} style=${color?'color:'+color:''}></ha-icon>`;
  const action = (label,name,fn,disabled=false,raised=false) => html`<button type="button" class=${raised?'action glass-primary':'action'} ?disabled=${disabled||card._busy} @click=${fn}>${icon(name)}<span>${label}</span></button>`;
  const optionLabels = id => (get(id)?.attributes.options||[]).filter(o=>o!=='unknown');
  const stateChip = (id,label,ico,problem=false,compact=false) => {
    const state=get(id)?.state, known=['on','off'].includes(state);
    const color=!known?'var(--secondary-text-color)':problem?(state==='off'?'var(--green-color)':'var(--red-color)'):(state==='on'?'var(--green-color)':'var(--secondary-text-color)');
    const switchEntity=id.startsWith('switch.');
    let status=fmt(id),remaining='';
    if(id===ids.drying&&state==='on') {
      const s=get(ids.dryTime)?.state;
      if(s!==undefined&&!['unknown','unavailable'].includes(s)&&Number.isFinite(Number(s))) {
        const minutes=Math.ceil(Number(s)/60);
        remaining=minutes>=60?Math.floor(minutes/60)+' h '+(minutes%60)+' min':minutes+' min';status=remaining;
      }
    }
    if(switchEntity){const config={entity:id,name:label,icon:ico,switch_style:card._config.switch_style||'liquid_glass',child_lock:card._config.child_lock,child_lock_entity:card._config.child_lock_entity};const visual={...switchVisual(config,card.hass.states),available:known&&!card._busy,color};return html`<div class=${compact?'dock-glass-control':'chip dock-tile dock-glass-control'} data-entity=${id} title=${label+': '+status}><dash6-glass-switch ._config=${config} data-style=${config.switch_style} .visual=${visual} .managed=${true} @toggle-request=${()=>card._toggle(id)}></dash6-glass-switch>${compact?(remaining?html`<span class="dry-remaining">${remaining}</span>`:''):html`<span>${label}<small>${status}</small></span>`}</div>`;}
    return html`<button type="button" class=${compact?'dock-icon-button':'chip dock-tile'} data-entity=${id} title=${label+': '+status} aria-label=${label+': '+status} aria-pressed=${switchEntity?String(state==='on'):'undefined'} ?disabled=${switchEntity&&(!known||card._busy)} @click=${()=>switchEntity?card._toggle(id):more(id)}>${icon(ico,color)}${compact?(remaining?html`<span class="dry-remaining">${remaining}</span>`:''):html`<span>${label}<small>${status}</small></span>`}</button>`;
  };
  const dockStatus = compact => html`
    ${stateChip(ids.drying,tr('Mopp-Trocknung','Mop drying'),'mdi:weather-windy',false,compact)}
    ${stateChip(ids.washing,tr('Mopp-Wäsche','Mop washing'),'mdi:waves',false,compact)}
    ${stateChip(ids.emptying,tr('Staubentleerung','Dust emptying'),'mdi:delete-empty',false,compact)}
    ${stateChip(ids.cleanWater,tr('Frischwassertank','Clean water tank'),'mdi:water-check',true,compact)}
    ${stateChip(ids.dirtyWater,tr('Schmutzwassertank','Dirty water tank'),'mdi:water-alert',true,compact)}`;
  card._renderDock = () => {
    const choosing=card._dockPage==='mode';
    const modeIcons={smart:'mdi:creation',light:'mdi:fan-speed-1',balanced:'mdi:fan-speed-2',max:'mdi:fan-speed-3'};
    return html`<dialog class="custom-dialog dock-dialog" aria-label=${tr('Basisstation','Dock')} @click=${e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))card._closeDock();}}>
      <div class="dialog-header"><div class="dock-heading">${choosing?html`<button type="button" class="close" aria-label=${tr('Zurück','Back')} @click=${()=>{card._dockPage='overview';card.requestUpdate();}}>${icon('mdi:arrow-left')}</button>`:html`<div class="dock-heading-icon">${icon('mdi:robot-vacuum')}</div>`}<div><div class="dialog-subtitle">${tr('Dominik 3 · Basisstation','Dominik 3 · Dock')}</div><h2>${choosing?tr('Entleerungsmodus','Emptying mode'):tr('Basisstation','Dock')}</h2></div></div><button type="button" class="close" aria-label=${tr('Schließen','Close')} @click=${card._closeDock}>${icon('mdi:close')}</button></div>
      <div class="dialog-body">${choosing?html`<p class="dock-hint">${tr('Antippen, um den Entleerungsmodus zu ändern.','Tap to change the emptying mode.')}</p><div class="empty-mode-grid">${optionLabels(ids.emptyMode).map(v=>html`<button type="button" class="choice-tile" data-empty-mode=${v} aria-pressed=${String(get(ids.emptyMode)?.state===v)} ?disabled=${card._busy||!valid(ids.emptyMode)} @click=${()=>card._perform(async()=>{await card._setOption(ids.emptyMode,v);card._dockPage='overview';})}>${icon(modeIcons[v]||'mdi:tune')}<span>${fmt(ids.emptyMode,v)}</span>${get(ids.emptyMode)?.state===v?html`<ha-icon class="selected-mark" .icon=${'mdi:check-circle'}></ha-icon>`:''}</button>`)}</div>`:html`<div class="dock-grid">${dockStatus(false)}<button type="button" class="chip dock-tile mode-tile" @click=${()=>{card._dockPage='mode';card.requestUpdate();}}>${icon('mdi:tune-variant','var(--primary-color)')}<span>${tr('Entleerungsmodus','Emptying mode')}<small>${fmt(ids.emptyMode)}</small></span></button></div>`}
      </div>
    </dialog>`;
  };

  const choiceIcons = {
    mode:{vacuum:'mdi:vacuum',vac_and_mop:'mdi:water-sync',mop:'mdi:water'},
    intensity:{off:'mdi:water-off',slight:'mdi:water-outline',low:'mdi:water-minus',medium:'mdi:water',moderate:'mdi:water-check',high:'mdi:water-plus',extreme:'mdi:waves'},
    route:{standard:'mdi:routes',deep:'mdi:layers',deep_plus:'mdi:layers-triple',fast:'mdi:fast-forward',smart_mode:'mdi:creation',custom:'mdi:tune'},
    fan:{quiet:'mdi:volume-low',balanced:'mdi:fan-speed-1',turbo:'mdi:fan-speed-2',max:'mdi:fan-speed-3',max_plus:'mdi:fan-plus'}
  };
  card._renderCustom = () => {
    const d=card._draft;
    const choose=(key,value)=>{d[key]=value;card.requestUpdate();};
    const tile=(key,value,label,ico,selected,fn,disabled=false)=>html`<button type="button" class="choice-tile" data-param=${key} data-value=${String(value)} aria-pressed=${String(selected)} ?disabled=${disabled||card._busy} @click=${fn}>${icon(ico)}<span>${label}</span>${selected?html`<ha-icon class="selected-mark" .icon=${'mdi:check-circle'}></ha-icon>`:''}</button>`;
    const group=(key,label,values,labelFor,disabled=false)=>html`<fieldset class="choice-group"><legend>${label}</legend><div class="choice-grid">${values.map(value=>tile(key,value,labelFor(value),choiceIcons[key]?.[value]||'mdi:tune',d[key]===value,()=>choose(key,value),disabled))}</div></fieldset>`;
    const roomIcons={wohnzimmer:'mdi:sofa',flur:'mdi:image-frame',badezimmer:'mdi:bathtub',schlafzimmer:'mdi:bed'};
    const roomOrder=['wohnzimmer','flur','badezimmer','schlafzimmer'];
    const rooms=[...CONFIG.areas].sort((a,b)=>roomOrder.indexOf(a.area_id)-roomOrder.indexOf(b.area_id));
    return html`<dialog class="custom-dialog cleaning-dialog" aria-label=${tr('Reinigung starten','Start cleaning')} @click=${e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))card._closeCustom();}}>
      <div class="dialog-header"><div><div class="dialog-subtitle">${get(ids.vacuum)?.attributes.friendly_name||'Dominik 3'}</div><h2>${tr('Reinigung starten','Start cleaning')}</h2></div><button type="button" class="close" aria-label=${tr('Schließen','Close')} @click=${card._closeCustom}>${icon('mdi:close')}</button></div>
      <div class="dialog-body">
        <fieldset class="choice-group"><legend>${tr('Räume','Rooms')}<small>${tr('Mehrfachauswahl','Select multiple')}</small></legend><div class="room-grid">${rooms.map(a=>{const room=card.hass.areas?.[a.area_id],n=a.roborock_area_id;return tile('rooms',n,room?.name||a.area_id,room?.icon||roomIcons[a.area_id]||'mdi:floor-plan',d.rooms.includes(n),()=>{d.rooms=d.rooms.includes(n)?d.rooms.filter(x=>x!==n):[...d.rooms,n];card.requestUpdate();});})}</div></fieldset>
        ${group('mode',tr('Reinigungsmodus','Cleaning mode'),optionLabels(ids.mode),v=>fmt(ids.mode,v),get(ids.mode)?.state==='unavailable')}
        ${group('intensity',tr('Wisch-Intensität','Mop intensity'),optionLabels(ids.intensity),v=>fmt(ids.intensity,v),d.mode==='vacuum'||get(ids.intensity)?.state==='unavailable')}
        ${group('route',tr('Wisch-Modus','Mop route'),optionLabels(ids.route),v=>fmt(ids.route,v),d.mode==='vacuum'||get(ids.route)?.state==='unavailable')}
        ${group('fan',tr('Saugstufe','Suction power'),(get(ids.vacuum)?.attributes.fan_speed_list||[]).filter(v=>!['off','custom','smart_mode'].includes(v)),v=>card.hass.formatEntityAttributeValue(get(ids.vacuum),'fan_speed',v),d.mode==='mop')}
        <fieldset class="choice-group"><legend>${tr('Durchgänge','Cycles')}</legend><div class="choice-grid">${[1,2,3].map(v=>tile('repeat',v,v+' ×','mdi:repeat',d.repeat===v,()=>choose('repeat',v)))}</div></fieldset>
        
      </div>
      <div class="dialog-actions"><span class="selection-summary">${d.rooms.length?tr(d.rooms.length===1?'1 Raum ausgewählt':d.rooms.length+' Räume ausgewählt',d.rooms.length===1?'1 room selected':d.rooms.length+' rooms selected'):tr('Bitte Räume auswählen','Select rooms to continue')}</span>${action(tr('Reinigung starten','Start cleaning'),'mdi:play',()=>card._perform(async()=>{await card._start({...d,rooms:[...d.rooms]});card._closeCustom();}),!d.rooms.length)}</div>
    </dialog>`;
  };
  card._maintenanceSelected = CONFIG.stats.default[0]?.entity;
  card._maintenanceHistory = {};
  card._maintenanceConfirm = false;
  card._maintenanceBusy = false;
  card._maintenanceError = '';
  card._maintenanceButton = sensorId => {
    const title=CONFIG.stats.default.find(item=>item.entity===sensorId)?.title;
    const buttons={
      Filter:'button.example_2',
      'Seitenbürste':'button.example_3',
      'Hauptbürste':'button.example_1',
      Sensoren:'button.example_4',
      'Schmutzfänger':undefined, ...CONFIG.reset_buttons
    };
    const id=buttons[title],state=id&&get(id);
    // Buttons store their last press timestamp. `unknown` before the first
    // press is normal and must not hide an otherwise available reset action.
    return valid(ids.vacuum)&&state&&state.state!=='unavailable'?id:null;
  };
  card._loadMaintenanceHistory = async sensorId => {
    if(card._maintenanceHistory[sensorId]?.loading)return;
    card._maintenanceHistory[sensorId]={loading:true,points:[],error:''};
    card.requestUpdate();
    try{
      const end=new Date(),start=new Date(end.getTime()-7*86400000);
      const path=`history/period/${encodeURIComponent(start.toISOString())}?filter_entity_id=${encodeURIComponent(sensorId)}&end_time=${encodeURIComponent(end.toISOString())}&minimal_response`;
      await waitForViewReady();if(!card.isConnected)return;const response=await card.hass.callApi('GET',path);
      const points=(Array.isArray(response?.[0])?response[0]:[])
        .map(row=>({x:Date.parse(row.last_changed||row.last_updated),y:Number(row.state)}))
        .filter(row=>Number.isFinite(row.x)&&Number.isFinite(row.y)).sort((a,b)=>a.x-b.x);
      card._maintenanceHistory[sensorId]={loading:false,points,error:''};
    }catch(error){
      card._maintenanceHistory[sensorId]={loading:false,points:[],error:''};reportError(card,error);
    }
    card.requestUpdate();
  };
  card._openMaintenance = sensorId => {
    card._maintenanceSelected=sensorId;
    card._maintenanceConfirm=false;
    card._maintenanceError='';
    card.requestUpdate();
    card.updateComplete.then(()=>card.shadowRoot.querySelector('.maintenance-dialog')?.showModal());
    card._loadMaintenanceHistory(sensorId);
  };
  card._chooseMaintenance = sensorId => {
    if(card._maintenanceBusy)return;
    card._maintenanceSelected=sensorId;
    card._maintenanceConfirm=false;
    card._maintenanceError='';
    card.requestUpdate();
    if(!card._maintenanceHistory[sensorId])card._loadMaintenanceHistory(sensorId);
  };
  card._resetMaintenance = async sensorId => {
    const buttonId=card._maintenanceButton(sensorId);
    if(!buttonId||!valid(ids.vacuum)||sensorId!==card._maintenanceSelected||!card._maintenanceConfirm||card._maintenanceBusy)return;
    card._maintenanceBusy=true;
    card._maintenanceError='';
    card.requestUpdate();
    try{
      await card.hass.callService('button','press',{entity_id:buttonId});
      card._maintenanceConfirm=false;
      card._maintenanceHistory[sensorId]=null;
      card._loadMaintenanceHistory(sensorId);
    }catch(error){reportError(card,error);}
    card._maintenanceBusy=false;
    card.requestUpdate();
  };
  card._renderMaintenance = () => {
    const items=CONFIG.stats.default,selected=card._maintenanceSelected;
    const item=items.find(row=>row.entity===selected)||items[0];
    const history=card._maintenanceHistory[item.entity];
    const buttonId=card._maintenanceButton(item.entity);
    const state=get(item.entity),value=Number(state?.state);
    const points=history?.points||[];
    const min=points.length?Math.min(...points.map(p=>p.y)):0;
    const max=points.length?Math.max(...points.map(p=>p.y)):1;
    const end=Date.now(),start=end-7*86400000;
    const span=Math.max(1,max-min);
    const px=time=>Math.max(0,Math.min(1000,(time-start)/(end-start)*1000));
    const py=value=>170-(value-min)/span*145;
    let line=points.length?`0,${py(points[0].y)}`:'';
    let previous=points[0]?.y;
    for(const point of points){line+=` ${px(point.x)},${py(previous)} ${px(point.x)},${py(point.y)}`;previous=point.y;}
    if(points.length)line+=` 1000,${py(previous)}`;
    return html`<style>${MAINTENANCE_CSS}</style><dialog class="maintenance-dialog" aria-label=${tr('Verschleißteile','Maintenance')} @click=${e=>{if(e.target===e.currentTarget)e.currentTarget.close()}}>
      <header><h2>${tr('Verschleißteile','Maintenance')}</h2><button class="maintenance-close" type="button" aria-label=${tr('Schließen','Close')} @click=${()=>card.shadowRoot.querySelector('.maintenance-dialog')?.close()}>${icon('mdi:close')}</button></header>
      <div class="maintenance-tabs" role="tablist" aria-label=${tr('Verschleißteil wählen','Choose maintenance item')}>
        ${items.map(row=>html`<button type="button" role="tab" aria-selected=${String(row.entity===item.entity)} ?disabled=${card._maintenanceBusy} @click=${()=>card._chooseMaintenance(row.entity)}>${tr(row.title,({'Seitenbürste':'Side brush','Hauptbürste':'Main brush','Sensoren':'Sensors','Schmutzfänger':'Strainer'})[row.title]||row.title)}</button>`)}
      </div>
      <div class="maintenance-body" role="tabpanel">
        <div class="maintenance-current">${Number.isFinite(value)?value.toLocaleString(card._de()?'de-DE':'en',{maximumFractionDigits:1}):'—'} ${item.unit}</div>
        <p class="maintenance-note">${tr('Verlauf der verbleibenden Zeit · letzte 7 Tage','Time remaining · last 7 days')}</p>
        ${history?.loading?html`<p>${tr('Verlauf wird geladen …','Loading history …')}</p>`:history?.error?html`<p class="maintenance-error">${history.error}</p>`:points.length?html`<svg class="maintenance-chart" viewBox="0 0 1000 190" preserveAspectRatio="none" role="img" aria-label=${tr('Verlauf von','History of')+' '+item.title}><polyline points=${line}></polyline></svg><div class="maintenance-chart-labels"><span>${tr('Vor 7 Tagen','7 days ago')}</span><span>${tr('Jetzt','Now')}</span></div><p class="maintenance-note">${tr('Wertebereich','Range')}: ${min.toLocaleString(card._de()?'de-DE':'en',{maximumFractionDigits:1})}–${max.toLocaleString(card._de()?'de-DE':'en',{maximumFractionDigits:1})} ${item.unit}</p>`:html`<p class="maintenance-note">${tr('Für diesen Zeitraum liegen keine Verlaufsdaten vor.','No history is available for this period.')}</p>`}
        ${buttonId?card._maintenanceConfirm?html`<div class="maintenance-confirm"><span>${tr('Wartung erledigt? Der Zähler wird unwiderruflich zurückgesetzt.','Maintenance done? This resets the counter and cannot be undone.')}</span><button type="button" class="confirm-yes" ?disabled=${card._maintenanceBusy} @click=${()=>card._resetMaintenance(item.entity)}>${tr('Ja, zurücksetzen','Yes, reset')}</button><button type="button" class="confirm-cancel" ?disabled=${card._maintenanceBusy} @click=${()=>{card._maintenanceConfirm=false;card.requestUpdate()}}>${tr('Abbrechen','Cancel')}</button></div>`:html`<button type="button" class="maintenance-reset" @click=${()=>{card._maintenanceConfirm=true;card.requestUpdate()}}>${tr(item.title+' zurücksetzen','Reset '+item.title)}</button>`:html`<p class="maintenance-note">${tr('Für dieses Bauteil ist kein Roborock-Reset-Button aktiviert.','No Roborock reset button is enabled for this item.')}</p>`}
        
      </div>
    </dialog>`;
  };
  card.render = function() {
    if(!this.hass||!get(ids.vacuum)) return html``;
    const robot=get(ids.vacuum),st=robot.state;
    const cleaning=st==='cleaning',active=['cleaning','paused','returning'].includes(st);
    const unavailable=['unknown','unavailable'].includes(st);
    const progress=get(ids.progress),progressKnown=progress&&!['unknown','unavailable'].includes(progress.state)&&Number.isFinite(Number(progress.state));
    const current=Number(progress?.state)||0;
    const stats=CONFIG.stats[cleaning?'cleaning':'default'].filter(s=>s.entity!==ids.progress);
    const battery=get(ids.battery);
    return html`<style>${materialCSS(STYLES)+surface+VACUUM_CONTROL_CSS+` .dock-mini{flex-wrap:wrap;gap:6px;max-width:100%;flex-shrink:1}.dock-glass-control{position:relative;display:flex;align-items:center;gap:8px;min-width:0}.dock-glass-control small{display:block}.dock-glass-control .dry-remaining{bottom:-3px}.dock-grid .dock-glass-control{flex-direction:column;text-align:center}`}</style><ha-card id="vacuum-card" lang=${card._de()?'de':'en'}>
      <header><button class="title-button" type="button" @click=${()=>more(ids.vacuum)}><ha-state-icon .hass=${this.hass} .stateObj=${robot}></ha-state-icon><strong>${robot.attributes.friendly_name||'Dominik 3'}</strong></button>${errorIndicator(card)}<div class="dock-mini" role="group" aria-label=${tr('Basisstation Schnellsteuerung','Dock quick controls')}>${dockStatus(true)}</div></header>
      <section class="status-panel"><div class="status-title">${fmt(ids.vacuum)}</div><div class="status-meta"><ha-relative-time .hass=${this.hass} .datetime=${robot.last_changed} capitalize></ha-relative-time><button class="battery" @click=${()=>more(ids.battery)}>${battery?fmt(ids.battery):'—'}<ha-state-icon .hass=${this.hass} .stateObj=${battery}></ha-state-icon></button></div><div class="robot-animation">${card._animation(robot)}</div></section>
      <div class="progress-row"><span>${tr('Reinigungsfortschritt','Cleaning progress')}</span><strong>${progressKnown?current.toLocaleString(card._de()?'de-DE':'en',{maximumFractionDigits:0})+' %':'—'}</strong><progress max="100" .value=${Math.max(0,Math.min(100,current))} aria-label=${tr('Reinigungsfortschritt','Cleaning progress')}></progress></div>
      <div class=${cleaning?'stats-grid cleaning-stats':'stats-grid'}>${stats.map(s=>{const obj=get(s.entity),n=Number(obj?.state),known=obj&&!['unknown','unavailable'].includes(obj.state)&&Number.isFinite(n);const labels={'Filter':'Filter','Seitenbürste':'Side brush','Hauptbürste':'Main brush','Sensoren':'Sensors','Schmutzfänger':'Strainer','Fortschritt':'Progress','Fläche':'Area','Dauer':'Duration'};return html`<button class="stat" @click=${()=>cleaning?more(s.entity):card._openMaintenance(s.entity)}><strong>${known?n.toLocaleString(card._de()?'de-DE':'en',{maximumFractionDigits:s.scale??0}):'—'} ${s.unit}</strong><span>${tr(s.title,labels[s.title]||s.title).replace('Seitenbürste','Seiten\u00adbürste').replace('Hauptbürste','Haupt\u00adbürste').replace('Schmutzfänger','Schmutz\u00adfänger')}</span></button>`;})}</div>
      <div class="actions-row primary-actions">
      ${cleaning?action(tr('Stop','Stop'),'mdi:stop',()=>card._perform(()=>call('vacuum','stop',{entity_id:ids.vacuum}))):action(st==='paused'?tr('Fortsetzen','Resume'):tr('Starten','Start'),'mdi:play',()=>card._perform(()=>st==='paused'?call('vacuum','start',{entity_id:ids.vacuum}):card._start()),unavailable||st==='returning',true)}
      ${action(tr('Individuell','Custom'),'mdi:tune',card._openCustom,unavailable,true)}
      </div><div class="actions-row secondary-actions">
      ${cleaning?action(tr('Pause','Pause'),'mdi:pause',()=>card._perform(()=>call('vacuum','pause',{entity_id:ids.vacuum}))):''}
      ${active&&!cleaning?action(tr('Stop','Stop'),'mdi:stop',()=>card._perform(()=>call('vacuum','stop',{entity_id:ids.vacuum}))):''}
      ${st!=='docked'?action(tr('Zur Basisstation','Return to dock'),'mdi:home-import-outline',()=>card._perform(()=>call('vacuum','return_to_base',{entity_id:ids.vacuum})),unavailable||st==='returning'):''}
      ${cleaning?action(tr('Mopp-Zwischenreinigung','Wash mop during cleaning'),'mdi:waves',card._intermediateWash,!valid(ids.washing)):''}
      
      </div>
      <div class="dock-locate-row">${action(tr('Lokalisieren','Locate'),'mdi:map-marker',()=>card._perform(()=>call('vacuum','locate',{entity_id:ids.vacuum})),unavailable)}<div class="dock-launcher-wrap"><button type="button" class="dock-launcher" @click=${card._openDock}><span class="dock-launcher-icon">${icon('mdi:robot-vacuum')}</span><span><strong>${tr('Basisstation','Dock')}</strong><small>${tr('Pflege & Einstellungen','Care & settings')}</small></span></button></div></div>
      
      </ha-card>${card._renderCustom()}${card._renderDock()}${card._renderMaintenance()}`;
  };

}
